import java.io.IOException; import java.nio.file.*; import java.util.*; public class Cleaner { private static final Map<String, String> EXTENSION_MAP = Map.ofEntries( Map.entry(".jpg", "Images"), Map.entry(".jpeg", "Images"), Map.entry(".png", "Images"), Map.entry(".gif", "Images"), Map.entry(".pdf", "Documents"), Map.entry(".docx", "Documents"), Map.entry(".txt", "Documents"), Map.entry(".xlsx", "Documents"), Map.entry(".exe", "Installers"), Map.entry(".msi", "Installers"), Map.entry(".zip", "Archives"), Map.entry(".rar", "Archives"), Map.entry(".7z", "Archives"), Map.entry(".py", "Code"), Map.entry(".java", "Code"), Map.entry(".html", "Code"), Map.entry(".mp3", "Audio_Video"), Map.entry(".mp4", "Audio_Video") ); public static void main(String[] args) { Path downloadsPath = Paths.get(System.getProperty("user.home"), "Downloads"); System.out.println("Scanning: " + downloadsPath); int movedCount = 0; try (DirectoryStream<Path> stream = Files.newDirectoryStream(downloadsPath)) { for (Path file : stream) { if (Files.isDirectory(file)) continue; String fileName = file.getFileName().toString(); String ext = getFileExtension(fileName); String targetFolder = EXTENSION_MAP.getOrDefault(ext, "Others"); Path targetDir = downloadsPath.resolve(targetFolder); Files.createDirectories(targetDir); Path destination = targetDir.resolve(fileName); if (Files.exists(destination)) { destination = targetDir.resolve("copy_" + fileName); } Files.move(file, destination, StandardCopyOption.REPLACE_EXISTING); System.out.println("Moved: " + fileName + " to " + targetFolder); movedCount++; } System.out.println("Done! Organized " + movedCount + " files."); } catch (IOException e) { System.out.println("Error: " + e.getMessage()); } } private static String getFileExtension(String fileName) { int i = fileName.lastIndexOf('.'); return i > 0 ? fileName.substring(i).toLowerCase() : ""; } } 
